import observed from '../../../fixtures/ordering-observed.json';
import auditObserved from '../../../fixtures/ordering-audit-observed.json';
import {
  ui, text, compact, visitProduct, observeQuotes, productIdentity,
  waitForQuote, selectedPackage, summary, currencyPresentation, pressButtonEnter
} from '../../../support/ordering';

describe('M03 P01/P02/P03 + M04 P04 — real guest, read-only ordering subsets', () => {
  it('P01-ORD01 — catalog identity leads to the matching product details', () => {
    observeQuotes();
    cy.visit('/shop');
    cy.contains('main article h3', observed.product.name).closest('article').within(() => {
      cy.get('a[href^="/products/"]').should('have.length', 1)
        .and('have.attr', 'href', observed.product.path).click();
    });
    productIdentity();
    waitForQuote(1);
    // Commercial copy, shipping accuracy, inventory counts and prices are gated.
  });

  it('P02-ORD01 — thumbnail Enter activation changes and restores the loaded image', () => {
    visitProduct();
    const mainImage = 'main button[aria-label="بزرگنمایی تصاویر بلک فرایدی"] img';
    const second = 'main button[aria-label="مشاهده تصویر 2"]';
    const first = 'main button[aria-label="مشاهده تصویر 1"]';
    cy.get(first + ' img').invoke('attr', 'src').then(firstSrc => {
      cy.get(second + ' img').invoke('attr', 'src').then(secondSrc => {
        expect(secondSrc, 'distinct observed thumbnail').not.eq(firstSrc);
        cy.get(second).should('be.visible').focus().should('be.focused');
        pressButtonEnter();
        cy.get(mainImage).should('have.attr', 'src', secondSrc)
          .and('be.visible').and($img => expect($img[0].naturalWidth).greaterThan(0));
        cy.get(first).focus().should('be.focused');
        pressButtonEnter();
        cy.get(mainImage).should('have.attr', 'src', firstSrc)
          .and('be.visible').and($img => expect($img[0].naturalWidth).greaterThan(0));
      });
    });
  });

  it('P03-ORD01 — package change reconciles identity and labels at quantity two', () => {
    visitProduct();
    cy.get(ui.increase).click();
    waitForQuote(2);
    cy.contains('main button', observed.packages.alternate.title).click();
    waitForQuote(2, observed.packages.alternate);
    selectedPackage(observed.packages.alternate);
    productIdentity();
    currencyPresentation();
    // Label multiplication is independent of quote money. No add-to-cart action.
  });

  it('P03-ORD02 — narrow-view package selection accepts keyboard Enter', () => {
    cy.viewport(390, 844);
    visitProduct();
    cy.contains('main button', observed.packages.alternate.title)
      .should('be.visible').focus().should('be.focused');
    pressButtonEnter();
    waitForQuote(1, observed.packages.alternate);
    selectedPackage(observed.packages.alternate);
    productIdentity();
  });

  it('P03-ORD03 — narrow purchase bar agrees with the settled main selection', () => {
    cy.viewport(390, 844);
    visitProduct();
    cy.get(ui.increase).click();
    waitForQuote(2);
    selectedPackage(observed.packages.default);
    cy.get(ui.mobileBar).should('be.visible');
    cy.get(ui.mobileLabels).should($el => {
      expect(text($el.text()), 'mobile label count').eq('240 لیبل');
    });
    cy.get('main').should($main => {
      const mainTotal = compact($main.find('.total-value').text());
      const mobileTotal = compact($main.find('.mobile-bar-total').text()).replace(/^جمع:/, '');
      expect(mainTotal, 'settled displayed currency format').match(/^\d+ریال$/);
      expect(mobileTotal, 'retry both current UI values together; consistency only').eq(mainTotal);
    });
    cy.get(ui.mobileBar).find('button').should('be.visible')
      .and('contain.text', 'افزودن به سبد خرید');
    // Visibility is not proof of readiness or successful cart handoff.
  });

  it('P04-ORD01 — current product stepper declares its bounds and returns to one', () => {
    visitProduct();
    cy.get(ui.quantity).should('have.attr', 'type', 'number')
      .and('have.attr', 'min', observed.quantity.min)
      .and('have.attr', 'max', observed.quantity.max).and('have.value', '1');
    cy.get(ui.decrease).should('be.disabled');
    cy.get(ui.increase).should('be.enabled').click();
    waitForQuote(2);
    cy.get(ui.decrease).should('be.enabled').click();
    waitForQuote(1);
    cy.get(ui.decrease).should('be.disabled');
    selectedPackage(observed.packages.default);
    summary(1, observed.packages.default.labels);
    // Observed min/max are a dated single-product baseline, not approved rules.
  });

  [[1366, 900], [390, 844]].forEach(([width, height]) => {
    it(`P02-ORD02 — observed zoom dialog navigation and close lifecycle at ${width}x${height}`, () => {
      cy.viewport(width, height);
      visitProduct();
      const trigger = 'main button[aria-label="بزرگنمایی تصاویر بلک فرایدی"]';
      const dialog = '[role="dialog"][aria-labelledby="product-lightbox-title"]';
      const checkImage = numeral => {
        cy.get(dialog).should($dialog => {
          const $tab = $dialog.find(`[role="tab"][aria-label="تصویر ${numeral}"]`);
          expect($tab.attr('aria-selected'), 'requested image tab is selected').eq('true');
          expect($dialog.find('[role="tab"][aria-selected="true"]'), 'unique selected image').have.length(1);
          const image = $dialog.find('img[alt^="بلک فرایدی - تصویر "]')[0];
          expect(image, 'visible-image identity in inspected dialog').to.exist;
          expect(image.getAttribute('src'), 'dialog image matches selected thumbnail')
            .eq($tab.find('img').attr('src'));
          expect(image.naturalWidth, 'image finished loading').greaterThan(0);
        });
      };
      cy.get(trigger).focus().should('be.focused');
      pressButtonEnter();
      cy.get(dialog).should('be.visible').and('have.attr', 'aria-modal', 'true');
      cy.get('#product-lightbox-title').should('have.text', observed.product.name);
      cy.get(dialog).find('button[aria-label="بستن گالری"]').should('be.focused');
      checkImage('۱');
      cy.get(dialog).find('button[aria-label="تصویر بعدی"]').click();
      checkImage('۲');
      cy.get(dialog).find('button[aria-label="تصویر قبلی"]').click();
      checkImage('۱');
      cy.get(dialog).find('[role="tab"][aria-label="تصویر ۲"]').click();
      checkImage('۲');
      cy.get(dialog).find('button[aria-label="بستن گالری"]').click();
      cy.get(dialog).should('not.exist');
      productIdentity();
      summary(1, observed.packages.default.labels);
      selectedPackage(observed.packages.default);
      cy.get(trigger).click();
      cy.get(dialog).should('be.visible');
      cy.get(dialog).find('button[aria-label="بستن گالری"]').should('be.focused');
      cy.press(Cypress.Keyboard.Keys.ESC);
      cy.get(dialog).should('not.exist');
      productIdentity();
      // Focus restoration and wrap at either image boundary are separate gaps.
    });

    it(`P04-ORD02 — native quantity ArrowUp reconciles the selection at ${width}x${height}`, () => {
      cy.viewport(width, height);
      visitProduct();
      cy.get(ui.quantity).focus().should('be.focused');
      cy.press(Cypress.Keyboard.Keys.UP);
      cy.press(Cypress.Keyboard.Keys.TAB);
      waitForQuote(2);
      selectedPackage(observed.packages.default);
      productIdentity();
      // This is the observed in-range keyboard path, not unknown invalid-input policy.
    });
  });

  it('P03-ORD04 — default selection is unique and package round trip preserves quantity', () => {
    visitProduct();
    selectedPackage(observed.packages.default);
    cy.get(ui.increase).click();
    waitForQuote(2);
    cy.contains('main button', observed.packages.alternate.title).click();
    waitForQuote(2, observed.packages.alternate);
    selectedPackage(observed.packages.alternate);
    cy.contains('main button', auditObserved.thirdPackage.title).click();
    waitForQuote(2, auditObserved.thirdPackage);
    selectedPackage(auditObserved.thirdPackage);
    cy.contains('main button', observed.packages.default.title).click();
    waitForQuote(2, observed.packages.default);
    selectedPackage(observed.packages.default);
    productIdentity();
  });
});
